      allowedEnvironmentVariables:
        req.policy?.sanitizationConfig?.allowedEnvironmentVariables ?? [],
      blockedEnvironmentVariables:
        req.policy?.sanitizationConfig?.blockedEnvironmentVariables ?? [],
